//| Calculate bar info box colors and volume percentages             |
//+------------------------------------------------------------------+
void CalculateBarColorsAndPercentages(BarFootprintData &footprint)
  {
   //--- Compute the net delta for the full bar
   footprint.delta = footprint.totalUpVolume - footprint.totalDownVolume;
   //--- Compute the combined volume for percentage calculations
   double totalVolume = footprint.totalUpVolume + footprint.totalDownVolume;

if(totalVolume == 0)
     {
      //--- Default to neutral colors and zero percentages when no volume exists
      footprint.boxColor      = upColor1;
      footprint.textColor     = upColor1;
      footprint.upPercentage  = 0;
      footprint.downPercentage = 0;
      return;
     }

//--- Round percentages to whole numbers for display
   footprint.upPercentage   = MathRound(100 * footprint.totalUpVolume   / totalVolume);
   footprint.downPercentage = MathRound(100 * footprint.totalDownVolume / totalVolume);

if(footprint.delta > 0)
     {
      //--- Derive box color from bullish delta intensity
      double ratio = MathAbs(footprint.delta / totalVolume);
      footprint.boxColor = GetVolumeColor(true, ratio);
     }
   else if(footprint.delta < 0)
     {
      //--- Derive box color from bearish delta intensity
      double ratio = MathAbs(footprint.delta / totalVolume);
      footprint.boxColor = GetVolumeColor(false, ratio);
     }
   else
     {
      //--- Assign neutral color when delta is exactly zero
      footprint.boxColor = upColor1;
     }

//--- Identify the dominant side percentage for text color derivation
   double winningPercentage = (footprint.delta > 0) ? footprint.upPercentage : footprint.downPercentage;
   //--- Compute how far the dominant side exceeds 50%
   double percentAbove50 = winningPercentage - 50;
   //--- Clamp to zero so values below 50% do not produce negative ratios
   if(percentAbove50 < 0) percentAbove50 = 0;
   //--- Scale the excess to a 0–1 ratio for color intensity
   double textRatio = MathCeil(percentAbove50) / 50.0;
   //--- Assign the text color matching the dominant direction and intensity
   footprint.textColor = GetVolumeColor(footprint.delta > 0, textRatio);
  }
